head.script:
// 화면 리사이징

scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp = js_market;
scwin.gAcptNo;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM); // 법인코드 및 법인명(회사명) 관련
        await scwin.setSendInfo(); // 보내는 사람, 전화번호 설정
        Grd_com_isur.style.zIndex = 30;
        await scwin.setCode(); // 공시일자(from~to)
        scwin.init(); // 시장구분

        // 가우스헤더 셋팅
        const sbmOptions = {
            id : "sbm_dts_SmsInfo",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_SmsInfo=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        await scwin.search('N');
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30318.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    rdo_MKT_ID.setValue(scwin.gLdMktTp);
    if (js_market === "9") {
        rdo_MKT_ID.setDisabled(false);
        rdo_MKT_ID.addClass("TopCondition_Blue");
    } else {
        // 콘트롤 잠그기
        rdo_MKT_ID.setDisabled(true);
    }
    if (scwin.gLdMktTp === '1' || scwin.gLdMktTp === '2') {
        $c.cm.setColumnProp(grd_Grid, "SPOT_ISU_TRD_MKT_TP_CD_NM", "Show", false);
        panel_mkt.hide();
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name txb_ISUR_CD_onfocus
 * @description txb_ISUR_CD 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30318.txb_ISUR_CD_onfocus" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onblur
 * @description txb_ISUR_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_ISUR_CD.getValue() === "") {
            txb_COM_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30318.txb_ISUR_CD_onblur" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onkeyup
 * @description txb_ISUR_CD 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onkeyup = function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30318.txb_ISUR_CD_onkeyup" });
    }
};

/**
 * @method
 * @name btn_ISUR_CD_onclick
 * @description btn_ISUR_CD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_ISUR_CD_onclick = function() {
    try {
        $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM); // 법인명 검색 팝업
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30318.btn_ISUR_CD_onclick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30318.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30318.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30318.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30318.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30318.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else {
            return true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30318.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name dts_emp_OnFilter
 * @description emp On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_emp_OnFilter = function(row) {
    try {
        //  부서코드에  해당하는 사원을 가져온다.
        if (scwin.gDepCd === "" || scwin.gDepCd === "UPTEAM") {
            // 전체일 경우 모두 보여준다.
            return true;
        } else {
            if (dts_emp.getCellData(row, "dep_cd") === scwin.gDepCd ||
                dts_emp.getCellData(row, "dep_cd") === "UPTEAM" ||
                dts_emp.getCellData(row, "dep_cd") === "") {
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30318.dts_emp_OnFilter" });
    }
};

/**
 * @method
 * @name dts_dep_OnLoadCompleted
 * @description dts_dep 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_dep_OnLoadCompleted = function(rowcount) {
    try {
        if (js_dep_cd.substring(0, 2) === '26' || js_dep_cd.substring(0, 2) === '34') {
            $c.stf.copyDataSet(dts_dep, dts_dep1);
            scwin.addDsclTeamAll(rowcount);
            cmb_TeamList.setValue('UPTEAM');
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30318.dts_dep_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name cmb_TeamList_onselchange
 * @description cmb_TeamList onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_TeamList_onselchange = function() {
    try {
        scwin.gDepCd = $c.cp.valueOfIndex(cmb_TeamList, "VALUE", cmb_TeamList.getSelectedIndex());
        if (scwin.gDepCd === '' || scwin.gDepCd === 'UPTEAM') {
            cmb_EmpList.setValue('');
        }
        dts_emp.UseFilter = true;
        dts_emp.Filter();
        dts_emp.sort("DEP_CD", 0);
        // dts_emp.sort(); // W-Craft 주석처리
        if (scwin.gDepCd !== '' && scwin.gDepCd !== 'UPTEAM') {
            cmb_EmpList.trigger("onclick");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30318.cmb_TeamList_onselchange" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search('N'); // 조회 버튼
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30318.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadCompleted
 * @description dts_Grid 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    // FillGridHeaderTotalCnt(rowcount, panel_page);    //총 건수

};

/**
 * @method
 * @name grd_Grid_onheadcheckclick
 * @description grd_Grid onheadcheckclick 이벤트
 * @param {*} col col
 * @param {*} colid colid
 * @param {*} bCheck bCheck
 * @returns {void}
 * @hidden N
 */
scwin.grd_Grid_onheadcheckclick = function(col, colid, bCheck) {
    try {
        scwin.setCheckBox(colid, bCheck);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30318.grd_Grid_onheadcheckclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        await $c.win.alert("성공적으로 처리 되었습니다.");
        await scwin.search('N');
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30318.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert('trs_Save.OnFail() :' + trs_Save.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30318.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name btn_SDATE_onclick
 * @description btn_SDATE 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_SDATE_onclick = function() {
    try {
        popUpCalendar2(edt_SDATE); // 공시일자-종료일 이미지 버튼 클릭 시 달력 팝업
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30318.btn_SDATE_onclick" });
    }
};

/**
 * @method
 * @name btn_EDATE_onclick
 * @description btn_EDATE 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_EDATE_onclick = function() {
    try {
        popUpCalendar2(edt_EDATE); // 공시일자-시작일 이미지 버튼 클릭 시 달력 팝업
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30318.btn_EDATE_onclick" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = cmb_PeriodTp.getValue();
        $c.stf.setFromToDate(vTp, edt_SDATE, edt_EDATE); // 기간선택 콤보박스
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30318.cmb_PeriodTp_onselchange" });
    }
};

/**
 * @method
 * @name txa_title_onchange
 * @description txa_title 변경 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txa_title_onchange = function() {
    try {
        txb_title_size.setValue($c.stf.getStringSize(txa_title.getValue()));
        if ($c.stf.getStringSize(txa_title.getValue()) > 80) {
            txb_alert.setValue('가 초과되었습니다.');
            txa_title.Focus();
            return;
        } else {
            txb_alert.setValue('');
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30318.txa_title_onchange" });
    }
};

/**
 * @method
 * @name img_send_onclick
 * @description 「전송」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_send_onclick = async function() {
    try {
        await scwin.registerSMS();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30318.img_send_onclick" });
    }
};

/**
 * @method
 * @name cmb_SmsTp_onselchange
 * @description cmb_SmsTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_SmsTp_onselchange = function() {
    try {
        if (txb_toPhone.getValue() !== '') {
            scwin.smsTpSelect();
        } else {
            // alert('SMS 발송대상이 선택되지 않았습니다.\n발송대상을 선택하시기 바랍니다.');

        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30318.cmb_SmsTp_onselchange" });
    }
};

/**
 * @method
 * @name grd_Grid_OnClick
 * @description grd_Grid 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_Grid_OnClick = function(row, colid) {
    try {
        scwin.readSendSMSInfo(row, colid);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30318.grd_Grid_OnClick" });
    }
};

/**
 * @method
 * @name dts_SsnInfo_OnLoadCompleted
 * @description dts_SsnInfo 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_SsnInfo_OnLoadCompleted = function(rowcount) {
    try {
        const vSsnEmpName = dts_SsnInfo.getCellData(1, "SSN_EMP_NM"); // 세션 사용자 명
        const vSsnTelNo = dts_SsnInfo.getCellData(1, "SSN_TEL_NO"); // 세션 사용자 전화번호
        const vSsnDepNm = dts_SsnInfo.getCellData(1, "SSN_DEP_NM"); // 세션 사용자 부서명
        const vSsnDepCd = dts_SsnInfo.getCellData(1, "SSN_DEP_CD"); // 세션 사용자 부서코드

        // 세션ID를 파라미터로 조회된 결과를 '보내는사람', '보내는 번호' 항목에 할당
        txb_fromName.setValue(js_emp_nm);
        txb_fromPhone.setValue(vSsnTelNo);
        txb_depCd.setValue(vSsnDepCd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30318.dts_SsnInfo_OnLoadCompleted" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description 공시일자, 팀, 담당자 세팅
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;

    //  기간 from~ to  셋팅(공시일자)
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDATE.setValue($c.ut.cGetMinusDate2(vCurDate, 7)); // 1년전 날짜
    edt_EDATE.setValue(vCurDate); // 현재날짜

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)
    const sbmOptions = {
        id : "sbm_dts_dep",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_dep=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)
    const sbmOptions2 = {
        id : "sbm_dts_emp",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_emp=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name search
 * @description 조회 버튼
 * @param {*} pReload pReload
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function(pReload) {
    // 받는사람, 받는번호, 메세지 유형 초기화
    txb_toName.setValue('');
    txb_toPhone.setValue('');
    cmb_SmsTp.setSelectedIndex(0);
    txa_title.Text = '';
    const flag = rdo_MKT_ID.getValue();
    if (flag === "") {
        await $c.win.alert("[시장구분]을 선택하세요.");
        rdo_MKT_ID.focus();
        return;
    } else {
        scwin.gDepCd = cmb_TeamList.getValue();
        scwin.gEmpNo = cmb_EmpList.getValue();
        if (scwin.gEmpNo === "") {
            scwin.gEmpNo = '%';
        }
        if (scwin.gDepCd === "") {
            scwin.gDepCd = 'all';
        }
        let url = "/NoteMgt.do?method=listSmsService";
        url += "&MKT_ID=" + rdo_MKT_ID.getValue(); // 시장구분
        url += "&ISUR_CD=" + txb_ISUR_CD.getValue(); // 법인코드
        url += "&SDATE=" + edt_SDATE.getValue();
        url += "&EDATE=" + edt_EDATE.getValue();
        url += "&EMP_NO=" + scwin.gEmpNo; // 담당자
        url += "&DEP_CD=" + scwin.gDepCd; // 팀(부서코드)
        url += "&UP_DEP_CD=" + js_belngdepcd; // 상위부서코드
        url += "&SSN_ID=" + js_id; // 세션 아이디

        if (pReload !== 'Y') {
            // 자동refresh일때는 로그 없앰
        }
        const sbmOptions = {
            id : "sbm_dts_Grid",
            action : "&SCREN_ID=",
            ref : "",
            target : "dts_Grid=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
};

