///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name addDsclTeamAll
 * @description 공시팀 전체 목록에 추가
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.addDsclTeamAll = function(rowcount) {
    dts_dep.setCellData(2, "VALUE", 'UPTEAM');
    dts_dep.setCellData(2, "TEXT", '공시팀 전체');
    dts_dep.setCellData(2, "DEP_CD", 'UPTEAM');
    dts_dep.setBroadcast(false);
    for (let i = 3; i <= rowcount; i++) {
        dts_dep.setCellData(i, "VALUE", dts_dep1.getCellData(i - 1, "VALUE"));
        dts_dep.setCellData(i, "TEXT", dts_dep1.getCellData(i - 1, "TEXT"));
        dts_dep.setCellData(i, "DEP_CD", dts_dep1.getCellData(i - 1, "DEP_CD"));
    }
    dts_dep.setBroadcast(true, true);
    dts_dep.insertRow();
    dts_dep.setCellData(rowcount + 1, "VALUE", dts_dep1.getCellData(rowcount, "VALUE"));
    dts_dep.setCellData(rowcount + 1, "TEXT", dts_dep1.getCellData(rowcount, "TEXT"));
    dts_dep.setCellData(rowcount + 1, "DEP_CD", dts_dep1.getCellData(rowcount, "DEP_CD"));
};

/**
 * @method
 * @name setCheckBox
 * @description set Check Box 처리
 * @param {*} colid colid
 * @param {*} bCheck bCheck
 * @returns {void}
 * @hidden N
 */
scwin.setCheckBox = function(colid, bCheck) {
    let vcd = "";
    if (bCheck === '1') {
        vcd = "T";
    } else {
        vcd = "F";
    }
    grd_Grid.Redraw = false;
    dts_Grid.setBroadcast(false);
    for (let i = 1; i <= dts_Grid.getRowCount(); i++) {
        dts_Grid.setCellData(i, colid, vcd);
    }
    dts_Grid.setBroadcast(true, true);
    grd_Grid.Redraw = true;
};

/**
 * @method
 * @name reload
 * @description reload 처리
 * @param {*} pReload pReload
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.reload = async function(pReload) {
    await scwin.search(pReload);
    setTimeout("fn_Reload('Y')", 120000); // 2분

};

/**
 * @method
 * @name readSendSMSInfo
 * @description SMS 전송대상 선택 시
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.readSendSMSInfo = function(row, colid) {
    const vToPhone = dts_Grid.getCellData(row, "CELLPHONE_NO1"); // 받는사람 번호
    const vToName = dts_Grid.getCellData(row, "DISCLS_CHRG_NM1"); // 받는사람 명
    const vToComName = dts_Grid.getCellData(row, "COM_ABBRV"); // 받는사람 상장법인명

    txb_toName.setValue('[' + vToComName + ' / ' + vToName + ']');
    txb_toPhone.setValue(vToPhone);
    txb_toPhoneComNm.setValue(vToComName); // 문자전송 메세지에 받는사람 상장법인명 표기를 위해 임시로 저장

    // SMS전송대상 변경 시 메세지 내용 변경
    scwin.smsTpSelect();
};

/**
 * @method
 * @name registerSMS
 * @description SMS 전송 클릭
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.registerSMS = async function() {
    if (await scwin.checkForm()) {
        const msg = $c.stf.getMessageParam("MSG-A006", "전송");
        const res = window.confirm(msg);
        if (res) {
            dts_SmsInfo.insertRow();
            dts_SmsInfo.setCellData(1, "RECEIVER", txb_toPhone.getValue());
            dts_SmsInfo.setCellData(1, "SENDER", txb_fromPhone.getValue());
            dts_SmsInfo.setCellData(1, "MSG", txa_title.Text);
            dts_SmsInfo.setCellData(1, "DEP_CD", txb_depCd.getValue());
            dts_SmsInfo.setCellData(1, "NOTE_SEQ", dts_Grid.getCellData(dts_Grid.getRowPosition(), "NOTE_SEQ"));
            let url = "/NoteMgt.do?method=saveSmsSendService&inputMessageId=BIZSPT_SMS_SEND_INFO" + "&SCREN_ID=" + "ULDSTF30318.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
            trs_Save.Action = url;
            trs_Save.KeyName = "toinb_dataid4";
            trs_Save.KeyValue = "JSP(I:pInput=dts_SmsInfo)";
            trs_Save.post();
        }
    }
};

/**
 * @method
 * @name checkForm
 * @description SMS 전송 전 validation
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    if (txb_fromName.getValue() === "") {
        await $c.win.alert("세션정보를 받지 못했읍니다. 재 로그인 후 이용해 주세요");
        txb_fromName.focus();
        return false;
    }
    if (txb_toPhone.getValue() === "") {
        await $c.win.alert("메세지 전송 대상이 선택되지 않았습니다.\n위의 목록에서 대상을 선택(클릭)하세요");
        txb_toPhone.focus();
        return false;
    }
    if ($c.stf.getStringSize(txb_fromPhone.getValue()) > 20) {
        await $c.win.alert('보내는 번호가 20Byte가 초과되었습니다.');
        txb_fromPhone.focus();
        return false;
    }
    if (txa_title.getValue() === "") {
        await $c.win.alert("보내는 내용이 입력되지 않았습니다.\n메세지 유형을 선택하세요");
        cmb_SmsTp.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name smsTpSelect
 * @description 메세지 유형 콤보박스 선택 시
 * @returns {void}
 * @hidden N
 */
scwin.smsTpSelect = function() {
    const vSelectedVal = $c.cp.valueOfIndex(cmb_SmsTp, "VALUE", cmb_SmsTp.getSelectedIndex());

    /* 문자내용에 유가공시팀/코스닥공시팀 표기를 위해 선언하였으나, '공시팀'으로 일원화 됨에 따라 주석처리함
    var vSsnMKT = '';
    if(getObjectValue(rdo_MKT_ID) == '1'){
    	vSsnMKT = '유가';
    }else if(getObjectValue(rdo_MKT_ID) == '2'){
    	vSsnMKT = '코스닥';
    }
     */

    if (vSelectedVal === ' ') {
        txa_title.Text = '';
    } else {
        txa_title.Text = txb_toName.getValue() + ' ' + vSelectedVal + '(공시팀)';
    }
};
